import type { DotCanvasEngine } from '@/hooks/use-dot-canvas'

export interface DotMatrixTextOptions {
  text: string
  fontSize: number
  fontWeight: number
  fontFamily: string
  dotSize: number
  gap: number
  color: string
  align: 'left' | 'center' | 'right'
  duration: number
  stagger: number
  scatter: number
  order: 'random' | 'left' | 'center'
  fitWidth: boolean
  interactive: boolean
  radius: number
  strength: number
  seed: number
  points?: ReadonlyArray<DotMatrixPoint>
  links?: ReadonlyArray<DotMatrixLink>
  linkWidth: number
  squareSize: number
  squareRadius: number
  shapes?: ReadonlyArray<string>
}

const TAU = Math.PI * 2

// Point indices plus an optional width overriding linkWidth
