    let rows = 0
    for (const [c, r] of points) {
      cols = Math.max(cols, c + 1)
      rows = Math.max(rows, r + 1)
    }
    const pad = dotSize / 2
    const w = (cols - 1) * gap + dotSize
    const h = (rows - 1) * gap + dotSize
    const x0 =
      (align === 'left' ? 0 : align === 'right' ? this.width - w : (this.width - w) / 2) + pad
