      >
        <div
          className="uig-wheel-carousel__arc"
          style={{
            maskImage: edgeFade ? EDGE_MASK : undefined,
            WebkitMaskImage: edgeFade ? EDGE_MASK : undefined,
          }}
        >
          {items.map((item, index) => {
            const angle = index * spacing - view.rotation
            const distance = Math.abs(angle)
            const hidden = distance > half + spacing
            const rad = angle * DEG
            const y = centerY + radius * Math.sin(rad)
            const inset = APEX_INSET + radius * (1 - Math.cos(rad))
            const opacity = hidden ? 0 : 1 - 0.7 * Math.min(distance / half, 1)

            return (
              <button
                key={`${item.label}-${index}`}
                type="button"
                role="option"
                id={`${id}-${index}`}
                tabIndex={-1}
                data-index={index}
                aria-selected={index === view.active}
                onClick={() => {
                  engine.select(index)
                  wake()
                }}
                className="uig-wheel-carousel__label"
                style={{
                  left: onLeft ? 0 : 'auto',
                  right: onLeft ? 'auto' : 0,
                  fontSize: labelSize,
                  opacity,
                  visibility: hidden ? 'hidden' : undefined,
                  transform: `translate3d(${onLeft ? inset : -inset}px, ${y}px, 0) translateY(-50%)`,
                }}
              >
                {item.label}
              </button>
            )
          })}
        </div>
        {showMarker && (
          <span
            aria-hidden="true"
            className="uig-wheel-carousel__marker"
            style={{
              top: centerY,
              left: onLeft ? MARKER_INSET : 'auto',
              right: onLeft ? 'auto' : MARKER_INSET,
              transform: 'translateY(-50%)',
            }}
          />
        )}
      </div>
      <div className="uig-wheel-carousel__live" aria-live="polite">
        {activeItem?.label}
      </div>
    </div>
  )
}

const FRICTION = 3.2
const OUTSIDE_FRICTION = 18
const OUTSIDE_DRAG = 0.3
const HANDOVER_SPEED = 24
const SPRING = 220
const DAMPING = 2 * Math.sqrt(SPRING)
const SCROLL_PAUSE = 0.1

export class WheelCarouselEngine {
  rotation = 0
  velocity = 0
  idle = true
  count
  spacing
  snap
  momentum
  dragSpeed
  scrollSpeed
  instant
  mode = 'idle'
  target = 0
  dragRaw = 0
  dragDelta = 0
  sinceScroll = 0

  constructor(options, initialIndex = 0) {
    this.count = options.count
    this.spacing = options.spacing
    this.snap = options.snap
    this.momentum = options.momentum
    this.dragSpeed = options.dragSpeed
    this.scrollSpeed = options.scrollSpeed
    this.instant = options.instant
    this.rotation = this.clampIndex(initialIndex) * this.spacing
    this.target = this.rotation
  }

  get max() {
    return Math.max(0, this.count - 1) * this.spacing
  }

  get activeIndex() {
    return this.clampIndex(Math.round(this.rotation / this.spacing))
  }

  setOptions(next) {
    const index = this.activeIndex
    const previousSpacing = this.spacing
    if (next.count !== undefined) this.count = next.count
    if (next.spacing !== undefined) this.spacing = next.spacing
    if (next.snap !== undefined) this.snap = next.snap
    if (next.momentum !== undefined) this.momentum = next.momentum
    if (next.dragSpeed !== undefined) this.dragSpeed = next.dragSpeed
    if (next.scrollSpeed !== undefined) this.scrollSpeed = next.scrollSpeed
    if (next.instant !== undefined) this.instant = next.instant
    if (this.spacing !== previousSpacing) {
      this.rotation = this.clampIndex(index) * this.spacing
      this.target = this.rotation
      this.velocity = 0
      if (this.mode !== 'drag') this.mode = 'idle'
    }
    if (this.mode === 'idle') this.rotation = this.clamp(this.rotation)
    this.idle = this.mode === 'idle'
  }

  canScroll(direction) {
    if (direction > 0) return this.rotation < this.max - 0.001
    if (direction < 0) return this.rotation > 0.001
    return false
  }

  dragStart() {
    this.mode = 'drag'
    this.dragRaw = this.rotation
    this.velocity = 0
    this.dragDelta = 0
    this.idle = false
  }

  dragMove(dy) {
    if (this.mode !== 'drag') return
    this.dragRaw -= dy * this.dragSpeed
    const next = this.rubber(this.dragRaw)
    this.dragDelta += next - this.rotation
    this.rotation = next
  }

  dragEnd() {
    if (this.mode !== 'drag') return
    const outside = this.rotation < 0 || this.rotation > this.max
    if (this.instant || !this.momentum || outside) {
      this.settleTo(this.snap || outside ? this.nearest(this.rotation) : this.rotation)
      return
    }
    const projected = this.rotation + this.velocity / FRICTION
    this.target = this.snap ? this.nearest(projected) : this.clamp(projected)
    this.mode = 'coast'
    this.idle = false
  }

  scroll(delta) {
    if (this.mode === 'drag') return
    this.mode = 'scroll'
    this.velocity = 0
    this.sinceScroll = 0
    this.rotation = this.clamp(this.rotation + delta * this.scrollSpeed)
    this.idle = false
  }

  select(index) {
    if (this.mode === 'drag') return
    this.velocity = 0
    this.settleTo(this.clampIndex(index) * this.spacing)
  }

  tick(dt) {
    switch (this.mode) {
      case 'drag': {
        const sampled = this.dragDelta / Math.max(dt, 0.001)
        this.velocity += (sampled - this.velocity) * 0.5
        this.dragDelta = 0
        break
      }
      case 'coast': {
        const outside = this.rotation < 0 || this.rotation > this.max
        this.rotation += this.velocity * dt * (outside ? OUTSIDE_DRAG : 1)
        this.velocity *= Math.exp(-(outside ? OUTSIDE_FRICTION : FRICTION) * dt)
        const passed =
          this.velocity > 0 ? this.rotation >= this.target : this.rotation <= this.target
        if (passed || Math.abs(this.velocity) < HANDOVER_SPEED) this.mode = 'settle'
        break
      }
      case 'scroll': {
        this.sinceScroll += dt
        if (this.sinceScroll > SCROLL_PAUSE) {
          if (this.snap) this.settleTo(this.nearest(this.rotation))
          else this.mode = 'idle'
        }
        break
      }
    }
    if (this.mode === 'settle') {
      // Critically damped spring keeps velocity continuous after coasting
      const diff = this.target - this.rotation
      this.velocity += (SPRING * diff - DAMPING * this.velocity) * dt
      this.rotation += this.velocity * dt
      if (Math.abs(diff) < 0.01 && Math.abs(this.velocity) < 0.5) {
        this.rotation = this.target
        this.velocity = 0
        this.mode = 'idle'
      }
    }
    this.idle = this.mode === 'idle'
  }

  settleTo(target) {
    this.target = target
    if (this.instant) {
      this.rotation = target
      this.velocity = 0
      this.mode = 'idle'
    } else {
      this.mode = 'settle'
    }
    this.idle = this.mode === 'idle'
  }

  nearest(rotation) {
    return this.clamp(Math.round(rotation / this.spacing) * this.spacing)
  }

  clamp(rotation) {
    return Math.min(Math.max(rotation, 0), this.max)
  }

  clampIndex(index) {
    return Math.min(Math.max(index, 0), Math.max(0, this.count - 1))
  }
  // Overshoot past either end approaches two items and stops

  rubber(raw) {
    const limit = this.spacing * 2
    if (raw < 0) return -this.stretch(-raw, limit)
    if (raw > this.max) return this.max + this.stretch(raw - this.max, limit)
    return raw
  }

  stretch(distance, limit) {
    return (limit * distance) / (distance + limit)
  }
}

.uig-wheel-carousel {
  display: flex;
  align-items: center;
  gap: calc(0.25rem * 8);
}

.uig-wheel-carousel__photo {
  position: relative;
  flex-shrink: 0;
  overflow: hidden;
  border-radius: 0.75rem;
  border-style: var(--tw-border-style, solid);
  border-width: 1px;
  border-color: currentcolor;
  @supports (color: color-mix(in lab, red, red)) {
    border-color: color-mix(in oklab, currentcolor 10%, transparent);
  }
}

.uig-wheel-carousel__image {
  position: absolute;
  inset: 0px;
  height: 100%;
  width: 100%;
  object-fit: cover;
}

.uig-wheel-carousel__window {
  position: relative;
  width: 100%;
  min-width: 0px;
  flex: 1;
  cursor: grab;
  --tw-pan-x: pan-x;
  touch-action: var(--tw-pan-x,) var(--tw-pan-y,) var(--tw-pinch-zoom,);
  border-radius: 0.375rem;
  -webkit-user-select: none;
  user-select: none;
  &:focus-visible {
    outline-style: var(--tw-outline-style, solid);
    outline-width: 2px;
  }
  &:focus-visible {
    outline-offset: 4px;
  }
  &:focus-visible {
    outline-color: currentcolor;
  }
  &:active {
    cursor: grabbing;
  }
}

.uig-wheel-carousel__arc {
  position: absolute;
  inset: 0px;
  overflow: hidden;
}

.uig-wheel-carousel__label {
  position: absolute;
  top: 0px;
  left: 0px;
  display: block;
  cursor: pointer;
  --tw-leading: 1;
  line-height: 1;
  --tw-font-weight: 500;
  font-weight: 500;
  --tw-tracking: -0.025em;
  letter-spacing: -0.025em;
  white-space: nowrap;
}

.uig-wheel-carousel__marker {
  pointer-events: none;
  position: absolute;
  height: calc(0.25rem * 1.5);
  width: calc(0.25rem * 1.5);
  border-radius: calc(infinity * 1px);
  background-color: currentcolor;
}

.uig-wheel-carousel__live {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

