  'ease-out': 'cubic-bezier(0, 0, 0.58, 1)',
  'expo-out': 'cubic-bezier(0.16, 1, 0.3, 1)',
}

export function spineGalleryTiming(easing: SpineGalleryEasing) {
  return CURVES[easing] ?? CURVES.spring
