'use client'

import './image-reveal.css'
import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
} from 'react'
import { ImageRevealEngine, revealLayer } from './image-reveal.engine'

export interface ImageRevealItem {
  image: string
  alt?: string
}

export interface ImageRevealOptions {
  scrollPerItem: number
  stageSize: string
  startInset: number
  grain: number
  showProgress: boolean
  label: string
  smoothing: number
  viewportHeight: string
}

export interface ImageRevealProps extends Partial<ImageRevealOptions> {
  items: ImageRevealItem[]
  className?: string
  style?: CSSProperties
}

export const imageRevealDefaults: ImageRevealOptions = {
  scrollPerItem: 1600,
  stageSize: '576px',
  startInset: 0,
  grain: 0.35,
  showProgress: true,
  label: 'Scroll down to reveal the images',
  smoothing: 0.15,
  viewportHeight: '100dvh',
}

const MAX_DT = 1 / 30
const MOTION_QUERY = '(prefers-reduced-motion: reduce)'

function subscribeMotion(onChange: () => void) {
  const list = window.matchMedia(MOTION_QUERY)
  list.addEventListener('change', onChange)
  return () => list.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

function pct(fraction: number) {
  return `${(fraction * 100).toFixed(3)}%`
}

export function ImageReveal({
  items,
  scrollPerItem = imageRevealDefaults.scrollPerItem,
  stageSize = imageRevealDefaults.stageSize,
  startInset = imageRevealDefaults.startInset,
  grain = imageRevealDefaults.grain,
  showProgress = imageRevealDefaults.showProgress,
  label = imageRevealDefaults.label,
  smoothing = imageRevealDefaults.smoothing,
  viewportHeight = imageRevealDefaults.viewportHeight,
  className,
  style,
}: ImageRevealProps) {
  const count = items.length
  const reduced = useReducedMotion()
  const grainId = useId()
  const engineRef = useRef<ImageRevealEngine | null>(null)
  if (!engineRef.current) {
    engineRef.current = new ImageRevealEngine({ count, smoothing, startInset, instant: false })
  }
  const engine = engineRef.current
  const [progress, setProgress] = useState(0)
  const rootRef = useRef<HTMLDivElement>(null)
  const trackRef = useRef<HTMLDivElement>(null)
  const wakeRef = useRef<() => void>(() => {})

  const wake = useCallback(() => wakeRef.current(), [])

  const publish = useCallback(() => {
    const current = engine.current
    setProgress((previous) => (previous === current ? previous : current))
  }, [engine])

  useEffect(() => {
    engine.setOptions({ count, smoothing, startInset, instant: reduced })
    wake()
  }, [engine, wake, count, smoothing, startInset, reduced])

  useEffect(() => {
    const root = rootRef.current
    const track = trackRef.current
    if (!root || !track) return
    let visible = true
    let frame = 0
    let last = 0
    let first = true

    const loop = (now: number) => {
      frame = 0
      if (!visible) return
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 1 / 60
      last = now
      engine.tick(dt)
      publish()
      if (!engine.idle) frame = requestAnimationFrame(loop)
      else last = 0
    }

    const start = () => {
      if (frame || !visible) return
      last = 0
      frame = requestAnimationFrame(loop)
    }

    const stop = () => {
      if (frame) cancelAnimationFrame(frame)
      frame = 0
      last = 0
    }

    const measure = () => {
      const top = track.getBoundingClientRect().top
      engine.setTarget(-top / scrollPerItem, first)
      first = false
      start()
    }

    wakeRef.current = start
    measure()

    window.addEventListener('scroll', measure, { passive: true, capture: true })
    const resize = new ResizeObserver(measure)
    resize.observe(root)

    const intersection = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true
      if (visible) measure()
      else stop()
    })
    intersection.observe(root)

    const onVisibility = () => {
      if (document.hidden) stop()
      else start()
    }
    document.addEventListener('visibilitychange', onVisibility)

    return () => {
      stop()
      window.removeEventListener('scroll', measure, { capture: true })
      resize.disconnect()
      intersection.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
      wakeRef.current = () => {}
    }
  }, [engine, publish, scrollPerItem])

  const active = Math.min(Math.max(Math.floor(progress), 0), Math.max(0, count - 1))
  const activeItem = items[active]
  const itemProgress = count === 0 ? 0 : progress >= count ? 1 : progress - Math.floor(progress)
  const grainOpacity = Math.min(Math.max(grain, 0), 1)

  return (
    <div
      ref={rootRef}
      className={['uig-image-reveal', className].filter(Boolean).join(' ')}
      style={style}
    >
      {label && (
        <div className="uig-image-reveal__header">
          <p className="uig-image-reveal__label">{label}</p>
          <span aria-hidden="true" className="uig-image-reveal__line" />
        </div>
      )}
      <div
        ref={trackRef}
        className="uig-image-reveal__track"
        style={{ height: `calc(${count * scrollPerItem}px + ${viewportHeight})` }}
      >
        <div
          className="uig-image-reveal__viewport"
          style={{ height: viewportHeight, containerType: 'size' }}
        >
          <div
            className="uig-image-reveal__stage"
            style={{ height: `min(${stageSize}, 80cqh, 92cqw)` }}
          >
            {grainOpacity > 0 && (
              <svg className="uig-image-reveal__defs" aria-hidden="true">
                <filter id={grainId}>
                  <feTurbulence
                    type="fractalNoise"
                    baseFrequency="0.9"
                    numOctaves="2"
                    stitchTiles="stitch"
                  />
                  <feColorMatrix type="saturate" values="0" />
                </filter>
              </svg>
            )}
            {items.map((item, index) => {
              const layer = revealLayer(progress - index, startInset)
              const layerStyle: CSSProperties = {
                visibility: layer.visible ? 'visible' : 'hidden',
                clipPath: `inset(${pct(layer.clipTop)} ${pct(layer.clipSide)} 0 ${pct(layer.clipSide)})`,
                transform: `scale(${layer.scale.toFixed(4)})`,
                filter: `brightness(${layer.brightness.toFixed(3)}) contrast(${layer.contrast.toFixed(3)})`,
                willChange: 'transform',
              }
              return (
                <div key={index} className="uig-image-reveal__layer" style={layerStyle}>
                  <img
                    src={item.image}
                    alt={item.alt ?? ''}
                    draggable={false}
                    className="uig-image-reveal__image"
                  />
                  {grainOpacity > 0 && (
                    <svg
                      className="uig-image-reveal__grain"
                      style={{ opacity: grainOpacity, mixBlendMode: 'overlay' }}
                      aria-hidden="true"
                    >
                      <rect width="100%" height="100%" filter={`url(#${grainId})`} />
                    </svg>
                  )}
                </div>
              )
            })}
          </div>
          {showProgress && (
            <div aria-hidden="true" className="uig-image-reveal__progress">
              <div className="uig-image-reveal__rail" />
              <div
                className="uig-image-reveal__fill"
                style={{ transform: `scaleY(${itemProgress.toFixed(4)})` }}
              />
            </div>
          )}
        </div>
      </div>
      <div className="uig-image-reveal__live" aria-live="polite">
        {count > 0 ? activeItem?.alt || `Image ${active + 1} of ${count}` : ''}
      </div>
    </div>
  )
}

export interface ImageRevealEngineOptions {
  count: number
  smoothing: number
  startInset: number
  instant: boolean
}

export interface ImageRevealLayer {
  visible: boolean
  reveal: number
  clipTop: number
  clipSide: number
  scale: number
  brightness: number
  contrast: number
}

const SETTLE = 0.0005
const REVEAL_SHARE = 0.5
const END_SCALE = 0.75
const START_BRIGHTNESS = 3
const START_CONTRAST = 2.5

const HIDDEN: ImageRevealLayer = {
  visible: false,
  reveal: 0,
  clipTop: 1,
  clipSide: 0,
  scale: 1,
  brightness: START_BRIGHTNESS,
  contrast: START_CONTRAST,
}

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max)
}

// Scroll distance past the item's start, measured in items
export function revealLayer(progress: number, startInset: number): ImageRevealLayer {
  if (progress < 0 || progress >= 1 + REVEAL_SHARE) return HIDDEN
  const reveal = clamp(progress / REVEAL_SHARE, 0, 1)
  const settle = clamp(progress, 0, 1)
  return {
    visible: true,
    reveal,
    clipTop: 1 - reveal,
    clipSide: clamp(startInset, 0, 0.5) * (1 - reveal),
    scale: 1 - (1 - END_SCALE) * settle,
    brightness: START_BRIGHTNESS - (START_BRIGHTNESS - 1) * reveal,
    contrast: START_CONTRAST - (START_CONTRAST - 1) * reveal,
  }
}

export class ImageRevealEngine {
  target = 0
  current = 0
  idle = true
  count: number
  smoothing: number
  startInset: number
  instant: boolean

  constructor(options: ImageRevealEngineOptions) {
    this.count = options.count
    this.smoothing = options.smoothing
    this.startInset = options.startInset
    this.instant = options.instant
  }

  get max() {
    return Math.max(0, this.count)
  }

  get activeIndex() {
    return clamp(Math.floor(this.current), 0, Math.max(0, this.count - 1))
  }

  // Fill of the side bar, restarts for every item
  get itemProgress() {
    if (this.count === 0) return 0
    if (this.current >= this.count) return 1
    return this.current - Math.floor(this.current)
  }

  setOptions(next: Partial<ImageRevealEngineOptions>) {
    if (next.count !== undefined) this.count = next.count
    if (next.smoothing !== undefined) this.smoothing = next.smoothing
    if (next.startInset !== undefined) this.startInset = next.startInset
    if (next.instant !== undefined) this.instant = next.instant
    this.target = clamp(this.target, 0, this.max)
    this.current = clamp(this.current, 0, this.max)
    this.idle = Math.abs(this.target - this.current) < SETTLE
  }

  setTarget(t: number, jump = false) {
    this.target = clamp(t, 0, this.max)
    if (jump || this.instant) this.current = this.target
    this.idle = Math.abs(this.target - this.current) < SETTLE
    if (this.idle) this.current = this.target
  }

  tick(dt: number) {
    const diff = this.target - this.current
    if (Math.abs(diff) < SETTLE || this.instant) {
      this.current = this.target
      this.idle = true
      return
    }
    // Frame-rate independent lerp, same feel as smoothing at 60fps
    const rate = 1 - Math.pow(1 - clamp(this.smoothing, 0.01, 1), dt * 60)
    this.current += diff * rate
    this.idle = false
  }

  layerFor(index: number) {
    return revealLayer(this.current - index, this.startInset)
  }
}

