    const canvas = canvasRef.current
    const raster = reduced || !input || !canvas ? null : rasterize(input, canvas, value)
    if (!raster) {
      reset()
      return
    }
    engine.setOptions({ speed: FRONT_PX_PER_SECOND * RASTER_SCALE * speed })
    engine.load(raster.pixels)
    if (engine.done) {
