    <form
      noValidate
      onSubmit={handleSubmit}
      className={['uig-devouring-sign-in', className].filter(Boolean).join(' ')}
      style={style}
    >
      <label htmlFor={inputId} className="uig-devouring-sign-in__label">
        {label}
      </label>
      <div className="uig-devouring-sign-in__field" style={{ fontSize }}>
        <div className="uig-devouring-sign-in__row">
          <canvas
            ref={canvasRef}
