'use client'

import './devouring-sign-in.css'
import { useCallback, useEffect, useId, useRef, useState, useSyncExternalStore } from 'react'
import { DevouringSignInEngine } from './devouring-sign-in.engine'

export const devouringSignInDefaults = {
  placeholder: 'you@example.com',
  label: 'Email address',
  hint: '[ enter ↵ ]',
  fontSize: 60,
  speed: 1,
}

const MAX_DT = 1 / 30
const FRONT_PX_PER_SECOND = 240
const RASTER_SCALE = 2
const PASSES_PER_FRAME = 2
const MOTION_QUERY = '(prefers-reduced-motion: reduce)'

function subscribeMotion(onChange) {
  const list = window.matchMedia(MOTION_QUERY)
  list.addEventListener('change', onChange)
  return () => list.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}
// Paints input text at double resolution where the input shows

function rasterize(input, canvas, text) {
  const ctx = canvas.getContext('2d', { willReadFrequently: true })
  if (!ctx) return null
  const box = input.getBoundingClientRect()
  const host = canvas.getBoundingClientRect()
  canvas.width = Math.max(1, Math.round(host.width * RASTER_SCALE))
  canvas.height = Math.max(1, Math.round(host.height * RASTER_SCALE))
  const cs = getComputedStyle(input)
  ctx.setTransform(RASTER_SCALE, 0, 0, RASTER_SCALE, 0, 0)
  ctx.clearRect(0, 0, host.width, host.height)
  ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`
  if ('letterSpacing' in ctx) ctx.letterSpacing = cs.letterSpacing
  ctx.fillStyle = cs.color
  ctx.textBaseline = 'alphabetic'
  const metrics = ctx.measureText(text)
  const ascent = metrics.fontBoundingBoxAscent ?? 0
  const descent = metrics.fontBoundingBoxDescent ?? 0
  const x = box.left - host.left + parseFloat(cs.paddingLeft)
  const middle = box.top - host.top + box.height / 2
  ctx.fillText(text, x, middle + (ascent - descent) / 2)
  const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height)
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  return { ctx, pixels }
}

export function DevouringSignIn({
  placeholder = devouringSignInDefaults.placeholder,
  label = devouringSignInDefaults.label,
  hint = devouringSignInDefaults.hint,
  fontSize = devouringSignInDefaults.fontSize,
  speed = devouringSignInDefaults.speed,
  onSubmit,
  onChange,
  className,
  style,
}) {
  const reduced = useReducedMotion()
  const inputId = useId()
  const [value, setValue] = useState('')
  const [devouring, setDevouring] = useState(false)
  const [announce, setAnnounce] = useState('')
  const inputRef = useRef(null)
  const canvasRef = useRef(null)
  const ctxRef = useRef(null)
  const engineRef = useRef(null)
  if (!engineRef.current) {
    engineRef.current = new DevouringSignInEngine({
      speed: FRONT_PX_PER_SECOND * RASTER_SCALE,
      passes: PASSES_PER_FRAME,
    })
  }
  const engine = engineRef.current
  const emailRef = useRef('')
  const onChangeRef = useRef(onChange)

  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  const reset = useCallback(() => {
    setValue('')
    setDevouring(false)
    setAnnounce(`Submitted ${emailRef.current}`)
    onChangeRef.current?.('')
  }, [])

  const handleChange = (e) => {
    if (devouring) return
    setValue(e.target.value)
    onChange?.(e.target.value)
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    const email = value.trim()
    if (!email || devouring) return
    emailRef.current = email
    onSubmit?.(email)
    const input = inputRef.current
    const canvas = canvasRef.current
    const raster = reduced || !input || !canvas ? null : rasterize(input, canvas, value)
    if (!raster) {
      reset()

      return
    }
    engine.setOptions({ speed: FRONT_PX_PER_SECOND * RASTER_SCALE * speed })
    engine.load(raster.pixels)
    if (engine.done) {
      reset()

      return
    }
    ctxRef.current = raster.ctx
    setAnnounce('Submitting')
    setDevouring(true)
  }

  useEffect(() => {
    if (!devouring) return
    const ctx = ctxRef.current
    if (!ctx) return
    let frame = 0
    let last = 0
    let ended = false

    const end = () => {
      if (ended) return
      ended = true
      if (frame) cancelAnimationFrame(frame)
      frame = 0
      engine.drawStatic(ctx)
      reset()
    }

    const loop = (now) => {
      frame = 0
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 1 / 60
      last = now
      engine.tick(dt)
      engine.draw(ctx)
      if (engine.done) end()
      else frame = requestAnimationFrame(loop)
    }

    const onVisibility = () => {
      if (document.hidden) end()
    }
    document.addEventListener('visibilitychange', onVisibility)
    frame = requestAnimationFrame(loop)

    return () => {
      document.removeEventListener('visibilitychange', onVisibility)
      if (frame) cancelAnimationFrame(frame)
    }
  }, [devouring, engine, reset])

  return (
    <form
      noValidate
      onSubmit={handleSubmit}
      className={['uig-devouring-sign-in', className].filter(Boolean).join(' ')}
      style={style}
    >
      <label htmlFor={inputId} className="uig-devouring-sign-in__label">
        {label}
      </label>
      <div className="uig-devouring-sign-in__field" style={{ fontSize }}>
        <div className="uig-devouring-sign-in__row">
          <canvas
            ref={canvasRef}
            aria-hidden="true"
            role="presentation"
            className="uig-devouring-sign-in__canvas"
            style={{ opacity: devouring ? 1 : 0 }}
          />
          <input
            ref={inputRef}
            id={inputId}
            type="email"
            name="email"
            autoComplete="off"
            autoCorrect="off"
            spellCheck={false}
            placeholder={placeholder}
            value={value}
            onChange={handleChange}
            className="uig-devouring-sign-in__input"
            style={{ color: devouring ? 'transparent' : undefined }}
          />
          <button type="submit" aria-label="Submit email" className="uig-devouring-sign-in__submit">
            {value ? (
              <span className="uig-devouring-sign-in__hint">{hint}</span>
            ) : (
              <span className="uig-devouring-sign-in__arrow">→</span>
            )}
          </button>
        </div>
      </div>
      <div className="uig-devouring-sign-in__live" aria-live="polite">
        {announce}
      </div>
    </form>
  )
}

const FRAME = 1 / 60
const SHRINK_PER_PASS = 0.05
const MAX_PASSES = 6

export class DevouringSignInEngine {
  speed
  passes
  width = 0
  height = 0
  count = 0
  front = 0
  minX = 0
  done = true
  ox = new Float32Array(0)
  x = new Float32Array(0)
  y = new Float32Array(0)
  size = new Float32Array(0)
  head = 0
  tail = 0
  carry = 0

  constructor(options) {
    this.speed = options.speed
    this.passes = options.passes
  }

  setOptions(next) {
    if (next.speed !== undefined) this.speed = next.speed
    if (next.passes !== undefined) this.passes = next.passes
  }
  // Every covered pixel becomes a particle, sampled right to left

  load(pixels) {
    const { data, width, height } = pixels
    const ox = new Float32Array(width * height)
    const y = new Float32Array(width * height)
    let count = 0
    let minX = width
    for (let px = width - 1; px >= 0; px--) {
      for (let py = 0; py < height; py++) {
        if ((data[(py * width + px) * 4 + 3] ?? 0) === 0) continue
        ox[count] = px
        y[count] = py
        count++
        if (px < minX) minX = px
      }
    }
    this.width = width
    this.height = height
    this.count = count
    this.ox = ox.subarray(0, count)
    this.x = Float32Array.from(this.ox)
    this.y = y.subarray(0, count)
    this.size = new Float32Array(count).fill(1)
    this.head = 0
    this.tail = 0
    this.carry = 0
    this.minX = count ? minX : 0
    this.front = count ? (ox[0] ?? 0) + 1 : 0
    this.done = count === 0
  }

  tick(dt) {
    if (this.done) return
    this.front -= this.speed * dt
    while (this.tail < this.count && (this.ox[this.tail] ?? 0) >= this.front) this.tail++
    this.carry += (this.passes * dt) / FRAME
    const steps = Math.min(MAX_PASSES, Math.floor(this.carry))
    this.carry -= steps
    for (let pass = 0; pass < steps; pass++) {
      for (let i = this.head; i < this.tail; i++) {
        const size = this.size[i] ?? 0
        if (size <= 0) continue
        this.x[i] = (this.x[i] ?? 0) + (Math.random() > 0.5 ? 1 : -1)
        this.y[i] = (this.y[i] ?? 0) + (Math.random() > 0.5 ? 1 : -1)
        this.size[i] = size - SHRINK_PER_PASS * Math.random()
      }
    }
    while (this.head < this.tail && (this.size[this.head] ?? 0) <= 0) this.head++
    if (this.front < this.minX - 1 && this.head >= this.tail) this.done = true
  }
  // Text left of the front stays, only dust repaints

  draw(ctx) {
    const from = Math.max(0, Math.floor(this.front))
    ctx.clearRect(from, 0, this.width - from, this.height)
    for (let i = this.head; i < this.tail; i++) {
      const size = this.size[i] ?? 0
      const x = this.x[i] ?? 0
      if (size <= 0 || x <= from) continue
      ctx.fillRect(x - 0.5, (this.y[i] ?? 0) - 0.5, size + 1, size + 1)
    }
  }

  drawStatic(ctx) {
    ctx.clearRect(0, 0, this.width, this.height)
  }
}

