const TAU = Math.PI * 2
const PAD = 0.04
const ROUND = 'OCGQDSUBPR0689@oceabdgpqs'
const AUTO_PERIOD = 7
const LABEL_FONT = '11px ui-monospace, SFMono-Regular, Menlo, monospace'
const ARG_COUNT = {
  M: 2,
  L: 2,
  T: 2,
  H: 1,
  V: 1,
  C: 6,
  S: 4,
  Q: 4,
  A: 7,
  Z: 0,
}

function createCanvas(width, height) {
  if (typeof OffscreenCanvas !== 'undefined') return new OffscreenCanvas(width, height)
  if (typeof document === 'undefined') return null
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  return canvas
}

function context2d(canvas) {
  return canvas.getContext('2d')
}

function ease(t) {
  return 1 - Math.pow(1 - t, 3)
}

function clamp01(t) {
  return Math.min(Math.max(t, 0), 1)
}
// Bounding box of an SVG path from its points

function pathBox(d) {
  const tokens = d.match(/[MmLlHhVvCcSsQqTtAaZz]|-?\d*\.?\d+(?:e[-+]?\d+)?/g)
  if (!tokens) return null
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  let x = 0
  let y = 0
  let startX = 0
  let startY = 0
  let command = 'M'
  let i = 0
  const include = (px, py) => {
    minX = Math.min(minX, px)
    minY = Math.min(minY, py)
    maxX = Math.max(maxX, px)
    maxY = Math.max(maxY, py)
  }
  while (i < tokens.length) {
    const token = tokens[i] ?? ''
    if (/[A-Za-z]/.test(token)) {
      command = token
      i++
      if (command.toUpperCase() === 'Z') {
        x = startX
        y = startY
        continue
      }
    }
    const upper = command.toUpperCase()
    const relative = command !== upper
    const count = ARG_COUNT[upper] ?? 0
    const args = tokens.slice(i, i + count).map(Number)
    if (args.length < count) break
    i += count
    const ox = relative ? x : 0
    const oy = relative ? y : 0
    if (upper === 'H') {
      x = ox + (args[0] ?? 0)
    } else if (upper === 'V') {
      y = oy + (args[0] ?? 0)
    } else if (upper === 'A') {
      x = ox + (args[5] ?? 0)
      y = oy + (args[6] ?? 0)
    } else {
      for (let k = 0; k + 1 < args.length; k += 2)
        include(ox + (args[k] ?? 0), oy + (args[k + 1] ?? 0))
      x = ox + (args[count - 2] ?? 0)
      y = oy + (args[count - 1] ?? 0)
    }
    include(x, y)
    if (upper === 'M') {
      startX = x
      startY = y
      command = relative ? 'l' : 'L'
    }
  }
  if (!Number.isFinite(minX)) return null
  return { x: minX, y: minY, w: Math.max(maxX - minX, 1), h: Math.max(maxY - minY, 1) }
}

