    lineCtx.strokeStyle = o.color
    lineCtx.lineWidth = o.strokeWidth / scale
    lineCtx.lineJoin = 'round'
    lineCtx.setLineDash(o.dash > 0 ? [o.strokeWidth / scale, o.dash / scale] : [])
    lineCtx.stroke(path)
  }
