        ctx.setLineDash([3, 4])
        ctx.beginPath()
        ctx.rect(ax + 0.5, boxY + 0.5, size, size)
        ctx.moveTo(ax + 0.5, above ? boxY : glyph.top)
        ctx.lineTo(ax + 0.5, above ? bottom : boxY + size)
        ctx.moveTo(ax + size, above ? boxY : boxY + size)
        ctx.lineTo(glyph.left, above ? bottom : glyph.top)
