  inset-inline: 0px;
  bottom: calc(0.25rem * 6);
  text-align: center;
  font-size: 0.875rem;
  line-height: var(--tw-leading, calc(1.25 / 0.875));
  --tw-font-weight: 500;
  font-weight: 500;
