  const looping = loop && loopLength > 0
  const phase = looping ? ((view.offset % loopLength) + loopLength) % loopLength : view.offset
  const reach = looping ? Math.ceil((viewportWidth / 2 + lens) / loopLength) : 0
  const shift = maps?.shift ?? 0
  const trackX = viewportWidth / 2 - phase - reach * loopLength
  const captionGap = Math.round(cardHeight * CAPTION_GAP)
  const fade = reduced ? 0 : 250
  const activeItem = items[view.active]
  const counter = `${String(view.active + 1).padStart(2, '0')}/${String(count).padStart(2, '0')}`
  const copies = []
  for (let copy = -reach; copy <= reach; copy++) copies.push(copy)

  const renderCards = (ghost) =>
    copies.flatMap((copy) =>
      items.map((item, index) => {
        const cardStyle = {
          width: widths[index],
          height: cardHeight,
          transform: `scale(${view.scale})`,
        }
        const key = `${copy}-${index}`
        const image = (
          <img
            src={item.image}
            alt={ghost || copy !== 0 ? '' : (item.alt ?? item.title)}
            draggable={false}
            className="uig-lens-carousel__image block h-full w-full object-cover"
          />
        )
        if (ghost) {
          return (
            <div
              key={key}
              className="uig-lens-carousel__ghost shrink-0 overflow-hidden"
              style={cardStyle}
            >
              {image}
            </div>
          )
        }
        return (
          <button
            key={key}
            type="button"
            role="option"
            id={copy === 0 ? `${id}-${index}` : undefined}
            tabIndex={-1}
            data-index={index}
            aria-selected={index === view.active}
            aria-hidden={copy !== 0 || undefined}
            onClick={() => {
              engine.select(index)
              wake()
            }}
            className="uig-lens-carousel__card block shrink-0 cursor-pointer overflow-hidden"
            style={cardStyle}
          >
            {image}
          </button>
        )
      }),
    )

  const renderLens = (side) => {
    const left = side === 'left'
    const origin = left ? -margin : viewportWidth - lens - margin

    return (
      <div
        aria-hidden="true"
        className={`uig-lens-carousel__lens pointer-events-none absolute overflow-hidden ${left ? 'left-0' : 'right-0'}`}
        style={{ top: EDGE_TRIM - above, width: lens, height: sourceHeight - EDGE_TRIM * 2 }}
      >
        <div
          className="uig-lens-carousel__glass absolute"
          style={{
            top: -EDGE_TRIM,
            left: left ? -margin : undefined,
            right: left ? undefined : -margin,
            width: sourceWidth,
            height: sourceHeight,
            background,
            filter: `url(#${filterId}-${left ? 'l' : 'r'})`,
          }}
        >
          <div
            className="uig-lens-carousel__clone absolute left-0 flex"
            style={{
              top: above + shift,
              gap,
              transform: `translate3d(${trackX - origin + shift}px, 0, 0)`,
            }}
          >
            {renderCards(true)}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div
      className={['uig-lens-carousel', 'overflow-hidden', className].filter(Boolean).join(' ')}
      style={{ background, color, ...style }}
    >
      <svg className="uig-lens-carousel__defs absolute h-0 w-0" aria-hidden="true">
        <LensFilter
          id={`${filterId}-l`}
          width={sourceWidth}
          height={sourceHeight}
          maps={maps?.left}
          scale={maps?.scale ?? 0}
          blur={blur}
        />
        <LensFilter
          id={`${filterId}-r`}
          width={sourceWidth}
          height={sourceHeight}
          maps={maps?.right}
          scale={maps?.scale ?? 0}
          blur={blur}
        />
      </svg>
      <div className="uig-lens-carousel__stage flex h-full w-full flex-col items-center justify-center">
        {showCaption && (
          <div
            aria-hidden="true"
            className="uig-lens-carousel__caption pointer-events-none grid text-center"
            style={{ marginBottom: captionGap }}
          >
            {items.map((item, index) => (
              <div
                key={`${item.title}-${index}`}
                className="uig-lens-carousel__entry col-start-1 row-start-1"
                style={{
                  opacity: index === view.active ? 1 : 0,
                  transition:
                    index === view.active
                      ? `opacity ${fade}ms ease-out ${fade / 2}ms`
                      : `opacity ${fade / 2}ms ease-out`,
                }}
              >
                <p className="uig-lens-carousel__title text-base leading-[1.15] font-medium">
                  {item.title}
                </p>
                {item.subtitle && (
                  <p className="uig-lens-carousel__subtitle text-base leading-[1.15] opacity-55">
                    {item.subtitle}
                  </p>
                )}
              </div>
            ))}
          </div>
        )}
        <div
          ref={viewportRef}
          role="listbox"
          tabIndex={0}
          aria-label="Carousel"
          aria-orientation="horizontal"
          aria-activedescendant={`${id}-${view.active}`}
          className="uig-lens-carousel__viewport relative w-full cursor-grab touch-pan-y select-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-current active:cursor-grabbing"
          style={{ height: cardHeight }}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={() => finishDrag(true)}
          onPointerCancel={() => finishDrag(false)}
          onLostPointerCapture={() => finishDrag(false)}
          onClickCapture={onClickCapture}
          onKeyDown={onKeyDown}
        >
          <div
            className="uig-lens-carousel__window absolute inset-0"
            style={{ clipPath: `inset(0 ${lens}px)` }}
          >
            <div
              className="uig-lens-carousel__track absolute top-0 left-0 flex"
              style={{ gap, transform: `translate3d(${trackX}px, 0, 0)` }}
            >
              {renderCards(false)}
            </div>
          </div>
          {lens > 0 && renderLens('left')}
          {lens > 0 && renderLens('right')}
        </div>
        {showCaption && (
          <div
            className="uig-lens-carousel__footer flex justify-center"
            style={{ marginTop: captionGap }}
          >
            <span
              aria-hidden="true"
              className="uig-lens-carousel__counter rounded-md bg-current/10 px-4 py-2 text-base leading-[1.25] tabular-nums"
            >
              {counter}
            </span>
          </div>
        )}
      </div>
      <div className="uig-lens-carousel__live sr-only" aria-live="polite">
        {activeItem?.title}
      </div>
    </div>
  )
}

const THROW_TIME = 0.13
const TWEEN_DURATION = 0.75
const SCROLL_DURATION = 0.5
const SCROLL_PAUSE = 0.12
const RUBBER_LIMIT = 160
const SCALE_PER_SPEED = 2.6e-5
const SCALE_FLOOR = 0.85
const SCALE_SMOOTHING = 24
const DRAG_SAMPLE = 0.05
const FOCUS_Y = 0.39
const SHEAR_Y = 0.15
const SHEAR = 0.75
const FRINGE_RAMP = 0.3
const SMEAR_POWER = 1.5

export class LensCarouselEngine {
  offset = 0
  velocity = 0
  scale = 1
  idle = true
  points
  loopLength
  loop
  snap
  inertia
  instant
  mode = 'idle'
  from = 0
  target = 0
  elapsed = 0
  duration = TWEEN_DURATION
  dragRaw = 0
  dragDelta = 0
  dragTime = 0
  sinceScroll = 0

  constructor(options, initialIndex = 0) {
    this.points = options.points
    this.loopLength = options.loopLength
    this.loop = options.loop
    this.snap = options.snap
    this.inertia = options.inertia
    this.instant = options.instant
    this.offset = this.pointAt(initialIndex)
    this.target = this.offset
  }

  get min() {
    return this.points[0] ?? 0
  }

  get max() {
    return this.points[this.points.length - 1] ?? 0
  }

  get activeIndex() {
    return this.nearestIndex(this.offset)
  }

  setOptions(next) {
    const index = this.activeIndex
    const previous = this.points
    if (next.points !== undefined) this.points = next.points
    if (next.loopLength !== undefined) this.loopLength = next.loopLength
    if (next.loop !== undefined) this.loop = next.loop
    if (next.snap !== undefined) this.snap = next.snap
    if (next.inertia !== undefined) this.inertia = next.inertia
    if (next.instant !== undefined) this.instant = next.instant
    if (this.points !== previous && this.mode !== 'drag') {
      // Layout changed, keep the same card centred without animating
      this.offset = this.pointAt(index)
      this.target = this.offset
      this.velocity = 0
      this.mode = 'idle'
    }
    this.idle = this.mode === 'idle' && this.scale === 1
  }

  canScroll(direction) {
    if (this.loop) return direction !== 0
    if (direction > 0) return this.offset < this.max - 0.5
    if (direction < 0) return this.offset > this.min + 0.5
    return false
  }

  dragStart() {
    this.mode = 'drag'
    this.dragRaw = this.offset
    this.velocity = 0
    this.dragDelta = 0
    this.dragTime = 0
    this.idle = false
  }

  dragMove(dx) {
    if (this.mode !== 'drag') return
    this.dragRaw -= dx
    const next = this.loop ? this.dragRaw : this.rubber(this.dragRaw)
    this.dragDelta += next - this.offset
    this.offset = next
  }

  dragEnd() {
    if (this.mode !== 'drag') return
    const outside = !this.loop && (this.offset < this.min || this.offset > this.max)
    if (this.instant || !this.inertia || outside) {
      this.settleTo(this.snap || outside ? this.nearest(this.offset) : this.offset, TWEEN_DURATION)
      return
    }
    const projected = this.offset + this.velocity * THROW_TIME
    this.settleTo(this.snap ? this.nearest(projected) : this.clamp(projected), TWEEN_DURATION)
  }

  scroll(delta) {
    if (this.mode === 'drag') return
    this.mode = 'scroll'
    this.velocity = 0
    this.sinceScroll = 0
    this.offset = this.clamp(this.offset + delta)
    this.idle = false
  }

  select(index) {
    if (this.mode === 'drag') return
    this.velocity = 0
    this.settleTo(this.occurrence(index, 0), TWEEN_DURATION)
  }

  step(direction) {
    if (this.mode === 'drag') return
    const count = this.points.length
    if (!count) return
    let index = this.activeIndex + direction
    if (this.loop) index = ((index % count) + count) % count
    else index = Math.min(Math.max(index, 0), count - 1)
    this.velocity = 0
    this.settleTo(this.occurrence(index, direction), TWEEN_DURATION)
  }

  tick(dt) {
    switch (this.mode) {
      case 'drag': {
        // Pointer events are slower than frames, sample per move
        this.dragTime += dt
        if (this.dragDelta !== 0 || this.dragTime > DRAG_SAMPLE) {
          const sampled = this.dragDelta / Math.max(this.dragTime, 0.001)
          this.velocity += (sampled - this.velocity) * 0.6
          this.dragDelta = 0
          this.dragTime = 0
        }
        break
      }
      case 'tween': {
        this.elapsed = Math.min(this.elapsed + dt, this.duration)
        const t = this.elapsed / this.duration
        const remaining = 1 - t
        const distance = this.target - this.from
        this.offset = this.from + distance * (1 - remaining * remaining * remaining)
        this.velocity = (3 * distance * remaining * remaining) / this.duration
        if (t >= 1) {
          this.offset = this.target
          this.velocity = 0
          this.mode = 'idle'
        }
        break
      }
      case 'scroll': {
        this.sinceScroll += dt
        if (this.sinceScroll > SCROLL_PAUSE) {
          if (this.snap) this.settleTo(this.nearest(this.offset), SCROLL_DURATION)
          else this.mode = 'idle'
        }
        break
      }
    }
    const wanted = this.instant
      ? 1
      : Math.max(SCALE_FLOOR, 1 - Math.abs(this.velocity) * SCALE_PER_SPEED)
    this.scale += (wanted - this.scale) * Math.min(1, dt * SCALE_SMOOTHING)
    if (Math.abs(wanted - this.scale) < 0.0005) this.scale = wanted
    this.idle = this.mode === 'idle' && this.scale === wanted
  }

  settleTo(target, duration) {
    this.target = target
    if (this.instant || Math.abs(target - this.offset) < 0.5) {
      this.offset = target
      this.velocity = 0
      this.mode = 'idle'
    } else {
      this.from = this.offset
      this.elapsed = 0
      this.duration = duration
      this.mode = 'tween'
    }
    this.idle = false
  }

  pointAt(index) {
    const last = Math.max(0, this.points.length - 1)
    return this.points[Math.min(Math.max(index, 0), last)] ?? 0
  }
  // Nearest copy of a point, or next one in a direction

  occurrence(index, direction) {
    const point = this.pointAt(index)
    if (!this.loop || this.loopLength <= 0) return point
    const base = point + Math.floor((this.offset - point) / this.loopLength) * this.loopLength
    const candidates = [base - this.loopLength, base, base + this.loopLength]
    let best = base
    let bestDistance = Infinity
    for (const candidate of candidates) {
      const delta = candidate - this.offset
      if (direction > 0 && delta <= 0.5) continue
      if (direction < 0 && delta >= -0.5) continue
      const distance = Math.abs(delta)
      if (distance < bestDistance) {
        bestDistance = distance
        best = candidate
      }
    }
    return best
  }

  nearestIndex(offset) {
    let best = 0
    let bestDistance = Infinity
    for (let i = 0; i < this.points.length; i++) {
      const distance = Math.abs(this.occurrenceNear(this.points[i] ?? 0, offset) - offset)
      if (distance < bestDistance) {
        bestDistance = distance
        best = i
      }
    }
    return best
  }

  occurrenceNear(point, offset) {
    if (!this.loop || this.loopLength <= 0) return point
    const base = point + Math.floor((offset - point) / this.loopLength) * this.loopLength
    return offset - base > this.loopLength / 2 ? base + this.loopLength : base
  }

  nearest(offset) {
    return this.occurrenceNear(this.pointAt(this.nearestIndex(offset)), offset)
  }

  clamp(offset) {
    if (this.loop) return offset
    return Math.min(Math.max(offset, this.min), this.max)
  }

  rubber(raw) {
    if (raw < this.min) return this.min - this.stretch(this.min - raw)
    if (raw > this.max) return this.max + this.stretch(raw - this.max)
    return raw
  }

  stretch(distance) {
    return (RUBBER_LIMIT * distance) / (distance + RUBBER_LIMIT)
  }
}
// Near-linear ramp from the outer edge with a soft tail

function lensProfile(u) {
  if (u <= 0) return 1
  if (u >= 1) return 0
  return Math.pow(1 - u, 1.2) * (1 - u * u * u)
}

export function buildLensMaps(options) {
  const { lens, outer, inner, top, cardHeight, strength, fringe, step } = options
  const sourceWidth = outer + lens + inner
  const sourceHeight = Math.round(top * 2 + cardHeight)
  const width = Math.max(2, Math.ceil(sourceWidth / step))
  const height = Math.max(2, Math.ceil(sourceHeight / step))
  const focus = top + cardHeight / 2 + FOCUS_Y * cardHeight
  const shearFocus = top + cardHeight / 2 + SHEAR_Y * cardHeight
  const pivot = lens / 2
  const fringeY = fringe * 0.75
  const field = (x, y) => {
    const k = strength * lensProfile(x / lens)
    return [k * (pivot - x + SHEAR * (y - shearFocus)), k * (focus - y)]
  }

  let peak = 0
  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      const [dx, dy] = field(i * step - outer, j * step)
      peak = Math.max(peak, Math.abs(dx) + fringe, Math.abs(dy) + fringeY)
    }
  }
  const scale = Math.ceil(peak) * 2 + 4
  const shift = scale * (128 / 255 - 0.5)

  const taps = [1, 0, -1]
  const left = taps.map(() => new Uint8ClampedArray(width * height * 4))
  const right = taps.map(() => new Uint8ClampedArray(width * height * 4))
  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      const x = i * step - outer
      const [dx, dy] = field(x, j * step)
      const ramp = Math.min(1, Math.max(0, (1 - x / lens) / FRINGE_RAMP))
      const smear = Math.round(255 * Math.pow(lensProfile(x / lens), SMEAR_POWER))
      const at = (j * width + i) * 4
      for (let tap = 0; tap < 3; tap++) {
        const sign = taps[tap] ?? 0
        const tapX = dx + (sign * fringe * ramp) / 2
        const tapY = dy - (sign * fringeY * ramp) / 2
        const encodedY = Math.round(127.5 + (tapY / scale) * 255)
        const map = left[tap]
        const mirrored = right[tap]
        if (!map || !mirrored) continue
        map[at] = Math.round(127.5 + (tapX / scale) * 255)
        map[at + 1] = encodedY
        map[at + 2] = smear
        map[at + 3] = 255
        const mirror = (j * width + (width - 1 - i)) * 4
        mirrored[mirror] = Math.round(127.5 - (tapX / scale) * 255)
        mirrored[mirror + 1] = encodedY
        mirrored[mirror + 2] = smear
        mirrored[mirror + 3] = 255
      }
    }
  }
  return { width, height, left, right, scale, shift }
}

