  transitionKey: string
  children: ReactNode
  onComplete?: (key: string) => void
  className?: string
  style?: CSSProperties
}

export const windowTransitionDefaults: WindowTransitionOptions = {
  duration: 1100,
  easing: 'expo',
  windowSize: 320,
  radius: 16,
  dim: 0.35,
  shrink: 0.04,
  zoom: 1.12,
  origin: 'bottom',
