    const animations = [
      front.animate(frames.window, timing),
      content.animate(frames.content, timing),
      back.animate(frames.back, timing),
    ]
    let done = false
    const finish = () => {
      if (done) return
      done = true
      for (const animation of animations) animation.cancel()
      setLayers((state) =>
