export const windowEasings = {
  expo: 'cubic-bezier(0.16, 1, 0.3, 1)',
  ui: 'cubic-bezier(0.32, 0.72, 0, 1)',
  'ease-in-out': 'cubic-bezier(0.65, 0, 0.35, 1)',
  circ: 'cubic-bezier(0, 0.55, 0.45, 1)',
