const WINDOW_ASPECT = 0.62
const PILL_SCALE = 0.12
const EDGE_INSET = 40
const RISE_END = 0.3
const RISE_EASING = 'cubic-bezier(0.45, 0, 0.2, 1)'

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max)
