        transform: `translate3d(0, ${startY - cy}px, 0) scale(${zoom})`,
        offset: 0,
        easing: RISE_EASING,
      },
      { transform: `translate3d(0, 0, 0) scale(${midZoom})`, offset: RISE_END, easing },
      { transform: 'translate3d(0, 0, 0) scale(1)', offset: 1 },
    ],
    back,
  }
}

