    this.updateHover()
    this.idle = this.mode === 'auto' && auto === 0 && Math.abs(this.yawVelocity) < REST
  }

  draw(ctx: CanvasRenderingContext2D) {
    const { dotSize, color, landOpacity, oceanOpacity, backOpacity, atmosphere, markerSize } =
