      const x = ring * Math.sin(phi)
      const z = ring * Math.cos(phi)
      points[i * 3] = x
      points[i * 3 + 1] = y
      points[i * 3 + 2] = z
      const lat = Math.asin(y) / DEG
      const lng = Math.atan2(x, z) / DEG
      flags[i] = isLand(lat, lng) ? 1 : 0
