import './goo-carve-button.css'
import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type FocusEvent,
  type MouseEvent,
  type PointerEvent,
  type ReactNode,
} from 'react'
import { GooCarveButtonEngine, type GooCarveRest } from './goo-carve-button.engine'

export interface GooCarveButtonOptions {
  label: string
  href: string
  newTab: boolean
  fill: string
  textColor: string
  blobColor: string
  blobSize: number
  smoothing: number
  stretch: number
  radius: number
  paddingX: number
  paddingY: number
  fontSize: number
  fontWeight: number
  letterSpacing: number
  uppercase: boolean
  rest: GooCarveRest
  enterDuration: number
  leaveDuration: number
}

export interface GooCarveButtonProps extends Partial<GooCarveButtonOptions> {
  // Optional icon rendered before the label
  icon?: ReactNode
  onClick?: (event: MouseEvent<HTMLElement>) => void
  className?: string
  style?: CSSProperties
}

export const gooCarveButtonDefaults: GooCarveButtonOptions = {
  label: 'LIQUID CARVE',
  href: '',
  newTab: false,
  fill: '#f5f5f7',
  textColor: '#09090c',
  blobColor: '#09090c',
  blobSize: 100,
  smoothing: 0.5,
  stretch: 0.5,
  radius: 22,
  paddingX: 64,
  paddingY: 40,
  fontSize: 40,
  fontWeight: 600,
  letterSpacing: 0,
  uppercase: false,
  rest: 'visible',
  enterDuration: 350,
  leaveDuration: 300,
}

