    let interval = 1 / 60

    const apply = () => {
      const blob = engine.blob()
      const inverse = 1 / blob.scale
      blobRef.current?.setAttribute(
        'transform',
        `translate(${blob.x.toFixed(2)} ${blob.y.toFixed(2)}) rotate(${blob.angle.toFixed(2)}) scale(${blob.scale.toFixed(4)} ${inverse.toFixed(4)})`,
