    if (!focusRef.current) return
    focusRef.current = false
    if (!hoverRef.current) engine.setPointer(null)
    wake()
  }

  const blur = Math.min(12, Math.max(2, blobSize * 0.08))

  const shared = {
    ref: setRoot,
    className: [
      'uig-goo-carve-button',
      'relative inline-flex cursor-pointer select-none appearance-none items-center justify-center border-0 bg-transparent no-underline focus-visible:outline-2 focus-visible:outline-offset-4',
      className,
    ]
      .filter(Boolean)
      .join(' '),
    style: {
      padding: `${paddingY}px ${paddingX}px`,
      borderRadius: radius,
      color: textColor,
      outlineColor: fill,
      fontFamily: 'inherit',
      fontSize,
      fontWeight,
      lineHeight: 1.5,
      letterSpacing: `${letterSpacing}em`,
      textTransform: uppercase ? ('uppercase' as const) : undefined,
      ...style,
    },
    onPointerEnter,
    onPointerMove,
    onPointerLeave,
    onFocus,
    onBlur,
    onClick,
  }

  const content = (
    <>
      <svg aria-hidden="true" className="uig-goo-carve-button__surface" width="100%" height="100%">
        <defs>
          <filter id={gooId}>
            <feGaussianBlur in="SourceGraphic" stdDeviation={blur} result="blur" />
            <feColorMatrix in="blur" type="matrix" values={GOO_MATRIX} />
          </filter>
          <mask id={maskId}>
            <rect width="100%" height="100%" fill="#fff" />
            <svg x="50%" y="50%" width="100%" height="100%" overflow="visible">
              <g ref={blobRef}>
                <circle ref={circleRef} r={initialRadius} fill="#000" />
              </g>
            </svg>
          </mask>
        </defs>
        <g filter={`url(#${gooId})`}>
          <rect width="100%" height="100%" rx={radius} ry={radius} fill={blobColor} />
        </g>
        <g filter={`url(#${gooId})`}>
          <rect
            width="100%"
            height="100%"
            rx={radius}
            ry={radius}
            fill={fill}
            mask={`url(#${maskId})`}
          />
        </g>
      </svg>
      <span className="uig-goo-carve-button__label">
        {icon ? (
          <span className="uig-goo-carve-button__icon" aria-hidden="true">
            {icon}
          </span>
        ) : null}
        {label}
      </span>
    </>
  )

  if (href) {
    return (
      <a
        {...shared}
        href={href}
        target={newTab ? '_blank' : undefined}
        rel={newTab ? 'noopener noreferrer' : undefined}
      >
        {content}
      </a>
    )
  }
  return (
    <button {...shared} type="button">
      {content}
    </button>
  )
}

