    const count = Math.max(1, Math.round(this.options.blobs))
    while (this.ink.length < count) {
      const prev = this.ink[this.ink.length - 1]
      this.ink.push({ x: prev?.x ?? 0, y: prev?.y ?? 0, vx: 0, vy: 0, scale: 0 })
