  pillNavReduce,
  pillNavStep,
  pillNavTiming,
  pillNavTransition,
  type PillNavCommand,
  type PillNavCommandGroup,
  type PillNavPosition,
} from './pill-nav.engine'

export interface PillNavLink {
  label: string
  href: string
  external?: boolean
}

export interface PillNavMenuItem {
  label: string
  // Without a link the item renders as plain text
  href?: string
  description?: string
  external?: boolean
}

export interface PillNavMenuSection {
  title: string
  items: PillNavMenuItem[]
}

export interface PillNavOptions {
  brand: string
  brandHref: string
  hideOnScroll: boolean
  blur: number
  radius: number
  height: number
  maxWidth: number
  expandDuration: number
  position: PillNavPosition
  command: boolean
  searchPlaceholder: string
}

export interface PillNavProps extends Partial<PillNavOptions> {
  logo?: ReactNode
  links?: PillNavLink[]
  // First section fills the panel, the rest become rows
  menu?: PillNavMenuSection[]
  // Receives internal links instead of a full page load
  onNavigate?: (href: string) => void
  className?: string
  style?: CSSProperties
}

export const pillNavDefaults: PillNavOptions = {
  brand: 'Acme',
  brandHref: '/',
  hideOnScroll: false,
  blur: 12,
  radius: 16,
  height: 54,
  maxWidth: 768,
  expandDuration: 300,
  position: 'fixed',
  command: true,
  searchPlaceholder: 'Search pages and links',
}

const MOTION_QUERY = '(prefers-reduced-motion: reduce)'
const SURFACE = 'var(--uig-pill-nav-surface, color-mix(in srgb, currentColor 4%, Canvas))'
const EDGE = 'var(--uig-pill-nav-edge, color-mix(in srgb, currentColor 2%, Canvas))'
const RAISED =
  'var(--uig-pill-nav-raised, light-dark(Canvas, color-mix(in srgb, currentColor 8%, Canvas)))'
const LINE = 'var(--uig-pill-nav-line, color-mix(in srgb, currentColor 5%, transparent))'
const SHADOW = '0 4px 8px -2px var(--uig-pill-nav-shadow, rgb(0 0 0 / 0.06))'
const OVERLAY = 'var(--uig-pill-nav-overlay, rgb(0 0 0 / 0.2))'
const PANEL_ALPHA = 80
const PANEL_BLUR_RATIO = 2 / 3
const FOOTER_HINT = 'Open link'
const NO_LINKS: PillNavLink[] = []

function subscribeMotion(onChange: () => void) {
  const query = window.matchMedia(MOTION_QUERY)
  query.addEventListener('change', onChange)
  return () => query.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

function translucent(color: string, percent: number) {
  return `color-mix(in srgb, ${color} ${percent}%, transparent)`
}

function isPlainClick(event: MouseEvent) {
  return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey
}

function Icon({ d, size = 16 }: { d: string; size?: number }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className="uig-pill-nav__icon"
    >
      <path d={d} />
    </svg>
  )
}

const ICONS = {
  command:
    'M9 9h6v6H9zM9 9H6a3 3 0 1 1 3-3v3M15 9V6a3 3 0 1 1 3 3h-3M15 15h3a3 3 0 1 1-3 3v-3M9 15v3a3 3 0 1 1-3-3h3',
  expand:
    'M3 8V5a2 2 0 0 1 2-2h3M16 3h3a2 2 0 0 1 2 2v3M21 16v3a2 2 0 0 1-2 2h-3M8 21H5a2 2 0 0 1-2-2v-3',
  collapse:
    'M8 3v3a2 2 0 0 1-2 2H3M21 8h-3a2 2 0 0 1-2-2V3M16 21v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3',
  search: 'M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14ZM20.5 20.5l-4.5-4.5',
  arrow: 'M5 12h14M13 6l6 6-6 6',
  external: 'M7 17 17 7M8 7h9v9',
  enter: 'M20 5v7a3 3 0 0 1-3 3H5M9 11l-4 4 4 4',
} as const

export function PillNav({
  brand = pillNavDefaults.brand,
  brandHref = pillNavDefaults.brandHref,
  hideOnScroll = pillNavDefaults.hideOnScroll,
  blur = pillNavDefaults.blur,
  radius = pillNavDefaults.radius,
  height = pillNavDefaults.height,
  maxWidth = pillNavDefaults.maxWidth,
  expandDuration = pillNavDefaults.expandDuration,
  position = pillNavDefaults.position,
  command = pillNavDefaults.command,
  searchPlaceholder = pillNavDefaults.searchPlaceholder,
  logo,
  links = NO_LINKS,
  menu,
  onNavigate,
  className,
  style,
}: PillNavProps) {
  const reduced = useReducedMotion()
  const [state, dispatch] = useReducer(pillNavReduce, pillNavInitialState)
  const [paletteMounted, setPaletteMounted] = useState(false)
  const [scrollHidden, setScrollHidden] = useState(false)
  const [frameHeight, setFrameHeight] = useState<number | null>(null)
  const rootRef = useRef<HTMLDivElement>(null)
  const columnRef = useRef<HTMLElement>(null)
  const toggleRef = useRef<HTMLButtonElement>(null)
  const paletteRef = useRef<HTMLDivElement>(null)
  const panelId = useId()

  if (state.palette && !paletteMounted) setPaletteMounted(true)

  const sections = useMemo<PillNavMenuSection[]>(
    () => (menu && menu.length > 0 ? menu : [{ title: 'Menu', items: links }]),
    [menu, links],
  )
  const groups = useMemo(() => pillNavCommands(sections, links), [sections, links])
  const [primary, ...rows] = sections
  const hasMenu = (primary?.items.length ?? 0) > 0
  const open = state.menu
  const hidden = hideOnScroll && scrollHidden && !open && !state.palette
  const duration = reduced ? 0 : expandDuration
  const closedHeight = pillNavClosedHeight(height)
  const panelBlur = Math.round(blur * PANEL_BLUR_RATIO)
  const inner = Math.max(0, radius - 4)
  const gap = open ? pillNavTiming.gapOpen : pillNavTiming.gapClosed
  const fullHeight = position === 'absolute' ? '100%' : '100vh'
  const columnHeight =
    position === 'absolute' ? (frameHeight === null ? '100%' : frameHeight) : '100dvh'

  useEffect(() => {
    if (!open) return
    const onPointer = (event: PointerEvent) => {
      const column = columnRef.current
      if (column && event.target instanceof Node && !column.contains(event.target)) {
        dispatch('close-menu')
      }
    }
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== 'Escape') return
      dispatch('close-menu')
      toggleRef.current?.focus()
    }
    document.addEventListener('pointerdown', onPointer)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('pointerdown', onPointer)
      document.removeEventListener('keydown', onKey)
    }
  }, [open])

  useEffect(() => {
    if (!command) return
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key.toLowerCase() !== 'k' || !(event.metaKey || event.ctrlKey)) return
      event.preventDefault()
      dispatch('toggle-palette')
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [command])

  useEffect(() => {
    const frame = rootRef.current?.offsetParent
    if (position !== 'absolute' || !(frame instanceof HTMLElement)) return
    const observer = new ResizeObserver(() => setFrameHeight(frame.clientHeight))
    observer.observe(frame)
    return () => observer.disconnect()
  }, [position])

  useEffect(() => {
    const root = rootRef.current
    if (!hideOnScroll || !root || position === 'static') return
    const tracker = new PillNavScroll(closedHeight)
    const frame = position === 'absolute' ? root.offsetParent : null
    const read = (target: EventTarget | null) => {
      if (target instanceof Element) {
        if (root.contains(target) || paletteRef.current?.contains(target)) return
        setScrollHidden(tracker.update(target.scrollTop))
      } else setScrollHidden(tracker.update(window.scrollY))
    }
    const onScroll = (event: Event) => read(event.target === document ? null : event.target)
    const host: EventTarget = frame ?? window
    host.addEventListener('scroll', onScroll, { passive: true, capture: frame !== null })
    return () => {
      host.removeEventListener('scroll', onScroll, { capture: frame !== null })
      setScrollHidden(false)
    }
  }, [hideOnScroll, position, closedHeight])

  const follow = (event: MouseEvent, href: string, external: boolean, closes: boolean) => {
    if (closes) dispatch('close-menu')
    if (!onNavigate || external || !isPlainClick(event)) return
    event.preventDefault()
    onNavigate(href)
  }

  const go = (entry: PillNavCommand) => {
    dispatch('close-palette')
    if (entry.external) window.open(entry.href, '_blank', 'noopener,noreferrer')
    else if (onNavigate) onNavigate(entry.href)
    else window.location.assign(entry.href)
  }

  const linkProps = (href: string, external: boolean | undefined, closes: boolean) => ({
    href,
    target: external ? '_blank' : undefined,
    rel: external ? 'noreferrer' : undefined,
    onClick: (event: MouseEvent) => follow(event, href, external ?? false, closes),
  })

  return (
    <>
      <div
        ref={rootRef}
        className={['uig-pill-nav', className].filter(Boolean).join(' ')}
        style={{
          position,
          top: 0,
          left: 0,
          right: 0,
          zIndex: 50,
          marginInline: 'auto',
          width: '100%',
          maxWidth,
          height: open ? fullHeight : closedHeight,
          transform: hidden ? 'translateY(-100%)' : 'none',
          transition: pillNavTransition(duration),
          ...style,
        }}
        onFocus={() => setScrollHidden(false)}
      >
        <nav
          ref={columnRef}
          aria-label="Main"
          className="uig-pill-nav__column"
          style={{ height: columnHeight, gap, transition: pillNavGapTransition(duration) }}
        >
          <div
            className="uig-pill-nav__bar"
            style={{
              height,
              borderRadius: radius,
              borderWidth: 1,
              borderStyle: 'solid',
              borderColor: EDGE,
              background: SURFACE,
              boxShadow: SHADOW,
              backdropFilter: blur > 0 ? `blur(${blur}px)` : undefined,
              WebkitBackdropFilter: blur > 0 ? `blur(${blur}px)` : undefined,
            }}
          >
            <a {...linkProps(brandHref, false, true)} className="uig-pill-nav__brand">
              {logo && <span className="uig-pill-nav__logo">{logo}</span>}
              <span className="uig-pill-nav__name">{brand}</span>
            </a>
            <div className="uig-pill-nav__end">
              {links.map((link) => (
                <a
                  key={`${link.href}-${link.label}`}
                  {...linkProps(link.href, link.external, true)}
                  className="uig-pill-nav__link"
                >
                  {link.label}
                </a>
              ))}
              {(command || hasMenu) && (
                <div className="uig-pill-nav__actions">
                  {command && (
                    <button
                      type="button"
                      aria-label="Search"
                      aria-haspopup="dialog"
                      aria-expanded={state.palette}
                      aria-keyshortcuts="Meta+K Control+K"
                      className="uig-pill-nav__button"
                      style={{ borderRadius: inner, background: RAISED }}
                      onClick={() => dispatch('open-palette')}
                    >
                      <span
                        className="uig-pill-nav__press"
                        style={{
                          transitionDuration: `${pillNavTiming.press}ms`,
                          transitionTimingFunction: pillNavEase.press,
                        }}
                      >
                        <Icon d={ICONS.command} />
                      </span>
                    </button>
                  )}
                  {hasMenu && (
                    <button
                      ref={toggleRef}
                      type="button"
                      aria-label="Menu"
                      aria-expanded={open}
                      aria-controls={panelId}
                      className="uig-pill-nav__button"
                      style={{ borderRadius: inner, background: RAISED }}
                      onClick={() => dispatch('toggle-menu')}
                    >
                      <span
                        className="uig-pill-nav__press"
                        style={{
                          transitionDuration: `${pillNavTiming.press}ms`,
                          transitionTimingFunction: pillNavEase.press,
                        }}
                      >
                        <Icon d={open ? ICONS.collapse : ICONS.expand} />
                      </span>
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
          {hasMenu && primary && (
            <div
              id={panelId}
              inert={!open}
              className="uig-pill-nav__panel"
              style={{ gap, transition: pillNavGapTransition(duration) }}
            >
              <ul
                aria-label={primary.title}
                className="uig-pill-nav__list"
                style={{
                  borderRadius: radius,
                  background: translucent(SURFACE, PANEL_ALPHA),
                  backdropFilter: panelBlur > 0 ? `blur(${panelBlur}px)` : undefined,
                  WebkitBackdropFilter: panelBlur > 0 ? `blur(${panelBlur}px)` : undefined,
                }}
              >
                {primary.items.map((item) => (
                  <li key={`${item.href}-${item.label}`} className="uig-pill-nav__entry">
                    {item.href ? (
                      <a
                        {...linkProps(item.href, item.external, true)}
                        className="uig-pill-nav__item"
                      >
                        <span className="uig-pill-nav__label">{item.label}</span>
                        {item.description && (
                          <span
                            className="uig-pill-nav__hint"
                            style={{ transform: 'translateX(100%)' }}
                          >
                            {item.description}
                          </span>
                        )}
                      </a>
                    ) : (
                      <span className="uig-pill-nav__label">{item.label}</span>
                    )}
                  </li>
                ))}
              </ul>
              {rows.map((row) => (
                <div
                  key={row.title}
                  role="group"
                  aria-label={row.title}
                  className="uig-pill-nav__row"
                  style={{
                    borderRadius: radius,
                    background: translucent(SURFACE, PANEL_ALPHA),
                    backdropFilter: panelBlur > 0 ? `blur(${panelBlur}px)` : undefined,
                    WebkitBackdropFilter: panelBlur > 0 ? `blur(${panelBlur}px)` : undefined,
                  }}
                >
                  {row.items.map((item, index) =>
                    item.href ? (
                      <a
                        key={`${item.href}-${item.label}`}
                        {...linkProps(item.href, item.external, true)}
                        className="uig-pill-nav__row-link"
                      >
                        {item.label}
                      </a>
                    ) : (
                      <span
                        key={`${item.label}-${index}`}
                        className="uig-pill-nav__row-text"
                        style={{ opacity: index === 0 ? 1 : 0.6 }}
                      >
                        {item.label}
                      </span>
                    ),
                  )}
                </div>
              ))}
            </div>
          )}
        </nav>
      </div>
      {command && paletteMounted && (
        <PillNavPalette
          ref={paletteRef}
          open={state.palette}
          groups={groups}
          placeholder={searchPlaceholder}
          position={position}
          maxWidth={maxWidth}
          radius={radius}
          reduced={reduced}
          onClose={() => dispatch('close-palette')}
          onExited={() => setPaletteMounted(false)}
          onSelect={go}
        />
      )}
    </>
  )
}

interface PillNavPaletteProps {
  ref: Ref<HTMLDivElement>
  open: boolean
  groups: PillNavCommandGroup[]
  placeholder: string
  position: PillNavPosition
  maxWidth: number
  radius: number
  reduced: boolean
  onClose: () => void
  onExited: () => void
  onSelect: (entry: PillNavCommand) => void
}

function PillNavPalette({
  ref,
  open,
  groups,
  placeholder,
  position,
  maxWidth,
  radius,
  reduced,
  onClose,
  onExited,
  onSelect,
}: PillNavPaletteProps) {
  const [query, setQuery] = useState('')
  const [active, setActive] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const dialogRef = useRef<HTMLDivElement>(null)
  const overlayRef = useRef<HTMLDivElement>(null)
  const listRef = useRef<HTMLDivElement>(null)
  const exitedRef = useRef(onExited)
  const baseId = useId()
  const visible = useMemo(() => pillNavFilter(groups, query), [groups, query])
  const flat = useMemo(() => visible.flatMap((group) => group.commands), [visible])
  const orders = useMemo(() => new Map(flat.map((entry, order) => [entry.id, order])), [flat])
  const current = flat[Math.min(active, flat.length - 1)]
  const optionId = (entry: PillNavCommand) => `${baseId}-${entry.id}`
  const currentId = current ? optionId(current) : undefined

  useEffect(() => {
    exitedRef.current = onExited
  }, [onExited])

  useEffect(() => {
    const previous = document.activeElement
    inputRef.current?.focus()
    const lock = position !== 'absolute'
    const root = document.documentElement
    const overflow = root.style.overflow
    if (lock) root.style.overflow = 'hidden'
    return () => {
      if (lock) root.style.overflow = overflow
      if (previous instanceof HTMLElement && previous.isConnected) previous.focus()
    }
  }, [position])

  useEffect(() => {
    const dialog = dialogRef.current
    const overlay = overlayRef.current
    if (!dialog || !overlay) return
    if (reduced) {
      if (!open) exitedRef.current()
      return
    }
    const easing = pillNavEase.dialog
    const frames = pillNavDialogFrames(open)
    const fade = open ? [{ opacity: 0 }, { opacity: 1 }] : [{ opacity: 1 }, { opacity: 0 }]
    const body = dialog.animate(frames, { duration: pillNavTiming.dialog, easing, fill: 'both' })
    const shade = overlay.animate(fade, { duration: pillNavTiming.overlay, easing, fill: 'both' })
    if (!open) body.onfinish = () => exitedRef.current()
    return () => {
      body.onfinish = null
      body.cancel()
      shade.cancel()
    }
  }, [open, reduced])

  useEffect(() => {
    if (!currentId) return
    const option = listRef.current?.querySelector(`[id="${currentId}"]`)
    option?.scrollIntoView({ block: 'nearest' })
  }, [currentId])

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation()
      onClose()
      return
    }
    if (event.key === 'Tab') {
      event.preventDefault()
      return
    }
    if (event.key === 'Enter') {
      event.preventDefault()
      if (current) onSelect(current)
      return
    }
    const next = pillNavStep(event.key, Math.min(active, flat.length - 1), flat.length)
    if (next === null) return
    event.preventDefault()
    setActive(next)
  }

  return (
    <div
      ref={ref}
      className="uig-pill-nav__palette"
      style={{
        position: position === 'absolute' ? 'absolute' : 'fixed',
        zIndex: 40,
        pointerEvents: open ? 'auto' : 'none',
      }}
      onKeyDown={onKeyDown}
    >
      <div
        ref={overlayRef}
        aria-hidden="true"
        className="uig-pill-nav__overlay"
        style={{ background: OVERLAY, opacity: reduced && !open ? 0 : undefined }}
        onClick={onClose}
      />
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-label="Search"
        className="uig-pill-nav__dialog"
        style={{ maxWidth }}
      >
        <div
          className="uig-pill-nav__sheet"
          style={{
            borderRadius: radius + 8,
            borderWidth: 1,
            borderStyle: 'solid',
            borderColor: LINE,
            background: SURFACE,
            backdropFilter: 'blur(8px)',
            WebkitBackdropFilter: 'blur(8px)',
          }}
        >
          <div
            className="uig-pill-nav__search"
            style={{
              borderRadius: radius,
              borderWidth: 1,
              borderStyle: 'solid',
              borderColor: LINE,
              background: EDGE,
            }}
          >
            <span className="uig-pill-nav__search-icon">
              <Icon d={ICONS.search} />
            </span>
            <input
              ref={inputRef}
              type="text"
              role="combobox"
              aria-expanded
              aria-controls={`${baseId}-list`}
              aria-activedescendant={currentId}
              aria-autocomplete="list"
              aria-label={placeholder}
              autoComplete="off"
              spellCheck={false}
              placeholder={placeholder}
              value={query}
              onChange={(event) => {
                setQuery(event.target.value)
                setActive(0)
              }}
              className="uig-pill-nav__input"
            />
          </div>
          <div
            aria-hidden="true"
            className="uig-pill-nav__fade"
            style={{
              background: `linear-gradient(to bottom, ${SURFACE}, transparent)`,
              backdropFilter: 'blur(4px)',
              WebkitBackdropFilter: 'blur(4px)',
              maskImage: 'linear-gradient(black 60%, transparent)',
              WebkitMaskImage: 'linear-gradient(black 60%, transparent)',
            }}
          />
          <div
            ref={listRef}
            id={`${baseId}-list`}
            role="listbox"
            aria-label={placeholder}
            className="uig-pill-nav__results"
          >
            {visible.length === 0 && (
              <p className="uig-pill-nav__empty">Nothing matches that search.</p>
            )}
            {visible.map((group, groupIndex) => (
              <div
                key={group.title}
                role="group"
                aria-labelledby={`${baseId}-g${groupIndex}`}
                className="uig-pill-nav__group"
                style={{ paddingTop: groupIndex > 0 ? 0 : undefined }}
              >
                <div
                  id={`${baseId}-g${groupIndex}`}
                  className="uig-pill-nav__heading"
                  style={{ opacity: 0.6 }}
                >
                  {group.title}
                </div>
                {group.commands.map((entry) => {
                  const order = orders.get(entry.id) ?? 0
                  const selected = entry === current
                  return (
                    <div
                      key={entry.id}
                      id={optionId(entry)}
                      role="option"
                      aria-selected={selected}
                      className="uig-pill-nav__option"
                      style={{
                        borderRadius: Math.max(0, radius - 4),
                        background: selected ? EDGE : undefined,
                      }}
                      onPointerMove={() => {
                        if (!selected) setActive(order)
                      }}
                      onClick={() => onSelect(entry)}
                    >
                      <span className="uig-pill-nav__option-icon" style={{ opacity: 0.7 }}>
                        <Icon d={entry.external ? ICONS.external : ICONS.arrow} />
                      </span>
                      <span className="uig-pill-nav__option-label">{entry.label}</span>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
          <div
            className="uig-pill-nav__footer"
            style={{
              borderTopWidth: 1,
              borderTopStyle: 'solid',
              borderColor: LINE,
              background: translucent(EDGE, 50),
            }}
          >
            <span className="uig-pill-nav__footer-hint" style={{ opacity: 0.5 }}>
              <span
                className="uig-pill-nav__kbd"
                style={{
                  borderWidth: 1,
                  borderStyle: 'solid',
                  borderColor: 'color-mix(in srgb, currentColor 10%, transparent)',
                }}
              >
                <Icon d={ICONS.enter} size={12} />
              </span>
              {FOOTER_HINT}
            </span>
            {current && (
              <span className="uig-pill-nav__footer-href" style={{ opacity: 0.5 }}>
                <span className="uig-pill-nav__footer-text">{current.href}</span>
                <Icon d={ICONS.external} size={12} />
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

export type PillNavPosition = 'fixed' | 'absolute' | 'static'

export interface PillNavEntry {
  label: string
  href?: string
  description?: string
  external?: boolean
}

export interface PillNavCommand {
  id: string
  label: string
  href: string
  external: boolean
  keywords: string
}

export interface PillNavCommandGroup {
  title: string
  commands: PillNavCommand[]
}

export interface PillNavState {
  menu: boolean
  palette: boolean
}

export type PillNavEvent =
  'toggle-menu' | 'close-menu' | 'open-palette' | 'toggle-palette' | 'close-palette'

export const pillNavPositions = ['fixed', 'absolute', 'static'] as const

export const pillNavEase = {
  expand: 'cubic-bezier(0, 0, 0.58, 1)',
  gap: 'cubic-bezier(0.25, 0.1, 0.35, 1)',
  dialog: 'ease',
  press: 'cubic-bezier(0.4, 0, 0.2, 1)',
} as const

export const pillNavTiming = {
  dialog: 200,
  overlay: 150,
  press: 150,
  gapClosed: 3,
  gapOpen: 8,
  inset: 8,
} as const

export const pillNavInitialState: PillNavState = { menu: false, palette: false }

// The palette always opens over a collapsed menu
export function pillNavReduce(state: PillNavState, event: PillNavEvent): PillNavState {
  switch (event) {
    case 'toggle-menu':
      return { menu: !state.menu, palette: false }
    case 'close-menu':
      return state.menu ? { ...state, menu: false } : state
    case 'open-palette':
      return state.palette && !state.menu ? state : { menu: false, palette: true }
    case 'toggle-palette':
      return state.palette ? { ...state, palette: false } : { menu: false, palette: true }
    case 'close-palette':
      return state.palette ? { ...state, palette: false } : state
  }
}

export function pillNavClosedHeight(barHeight: number) {
  return pillNavTiming.inset + barHeight + 1
}

export function pillNavTransition(duration: number) {
  if (duration <= 0) return 'none'
  return [
    `height ${duration}ms ${pillNavEase.expand}`,
    `transform ${duration}ms ${pillNavEase.expand}`,
  ].join(', ')
}

export function pillNavGapTransition(duration: number) {
  return duration <= 0 ? 'none' : `gap ${duration}ms ${pillNavEase.gap}`
}

// Hides after a downward run, shows on any upward run
export class PillNavScroll {
  private anchor = 0
  private hidden = false
  private threshold: number
  private tolerance: number

  constructor(threshold: number, tolerance = 6) {
    this.threshold = threshold
    this.tolerance = tolerance
  }

  setThreshold(threshold: number) {
    this.threshold = threshold
  }

  reset(y = 0) {
    this.anchor = y
    this.hidden = false
  }

  update(y: number) {
    const delta = y - this.anchor
    if (y <= this.threshold) {
      this.hidden = false
      this.anchor = y
    } else if (delta > this.tolerance) {
      this.hidden = true
      this.anchor = y
    } else if (delta < -this.tolerance) {
      this.hidden = false
      this.anchor = y
    }
    return this.hidden
  }
}

export function pillNavCommands(
  sections: { title: string; items: PillNavEntry[] }[],
  links: PillNavEntry[],
  linksTitle = 'Links',
): PillNavCommandGroup[] {
  const seen = new Set<string>()
  const groups: PillNavCommandGroup[] = []
  const collect = (title: string, items: PillNavEntry[]) => {
    const commands: PillNavCommand[] = []
    for (const item of items) {
      if (!item.href || seen.has(item.href)) continue
      seen.add(item.href)
      commands.push({
        id: `${groups.length}-${commands.length}`,
        label: item.label,
        href: item.href,
        external: item.external ?? isExternal(item.href),
        keywords: [item.label, item.description ?? '', item.href, title].join(' ').toLowerCase(),
      })
    }
    if (commands.length > 0) groups.push({ title, commands })
  }
  for (const section of sections) collect(section.title, section.items)
  collect(linksTitle, links)
  return groups
}

// Label prefix beats label substring beats keyword substring
function score(command: PillNavCommand, query: string) {
  const label = command.label.toLowerCase()
  if (label.startsWith(query)) return 3
  if (label.includes(query)) return 2
  if (command.keywords.includes(query)) return 1
  return 0
}

export function pillNavFilter(groups: PillNavCommandGroup[], query: string) {
  const q = query.trim().toLowerCase()
  if (!q) return groups
  const out: PillNavCommandGroup[] = []
  for (const group of groups) {
    const ranked = group.commands
      .map((command, index) => ({ command, index, rank: score(command, q) }))
      .filter((entry) => entry.rank > 0)
      .sort((a, b) => b.rank - a.rank || a.index - b.index)
      .map((entry) => entry.command)
    if (ranked.length > 0) out.push({ title: group.title, commands: ranked })
  }
  return out
}

export function pillNavStep(key: string, index: number, count: number): number | null {
  if (count === 0) return null
  if (key === 'ArrowDown') return Math.min(index + 1, count - 1)
  if (key === 'ArrowUp') return Math.max(index - 1, 0)
  if (key === 'Home') return 0
  if (key === 'End') return count - 1
  return null
}

export function isExternal(href: string) {
  return /^[a-z][a-z0-9+.-]*:/i.test(href) && !href.startsWith('/')
}

export function pillNavDialogFrames(open: boolean): Keyframe[] {
  const hidden = { opacity: 0, transform: 'scale(0.95)' }
  const shown = { opacity: 1, transform: 'scale(1)' }
  return open ? [hidden, shown] : [shown, hidden]
}

