      <span className="uig-dynamic-island__status" role="status" aria-live="polite">
        {target?.label ?? current}
      </span>
      <DynamicIslandContext value={context}>
        {layers.map((layer) => {
          const item = states[layer.key]

          return (
            <div
              key={layer.id}
              ref={(el) => {
                if (el) layerEls.current.set(layer.id, el)
                return () => {
                  layerEls.current.delete(layer.id)
                }
              }}
              className="uig-dynamic-island__layer"
              style={{
                width: item?.width,
                height: item?.height,
                opacity: layer.shown ? 1 : 0,
                transform: 'translate(-50%, -50%)',
              }}
            >
              {item?.content}
            </div>
          )
        })}
      </DynamicIslandContext>
    </div>
  )
}

