} from 'react'
import { ImageWheel3DEngine, type ImageWheel3DMode } from './image-wheel-3d.engine'

export interface ImageWheel3DItem {
  image: string
  alt?: string
  title?: string
  href?: string
}

export type ImageWheel3DPreviewPosition = 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right'

export interface ImageWheel3DOptions {
  mode: ImageWheel3DMode
  repeat: number
  padding: number
  cardWidth: number
  cardHeight: number
  cornerRadius: number
  tilt: number
  fov: number
  elevation: number
  autoRotateSpeed: number
  wheelSpeed: number
  dragSpeed: number
  smoothing: number
  hoverLift: number
  parallax: boolean
  preview: boolean
  previewWidth: number
  previewHeight: number
