export class TextTunnelEngine implements DotCanvasEngine<WebGLRenderingContext> {
  idle = false
  options: TextTunnelOptions
  private width = 0
  private height = 0
  private dpr = 1
  private phase = 0
  private shiftX = 0
  private shiftY = 0
  private targetX = 0
  private targetY = 0
  private block = 1
  private textureKey = ''
  private program: Program | null = null

  constructor(options: TextTunnelOptions) {
    this.options = options
  }

