  rise: 0.613,
  stagger: 0.018,
  riseDistance: 1.056,
  openAt: 0.947,
  open: 0.605,
  firstCut: 0.75,
  interval: 0.36,
  lastHold: 0.44,
  expand: 0.965,
  fade: 0.35,
  slotRatio: 1.1,
  clipOvershoot: 0.02,
}

export const splitWordLoaderBezier = [0.76, 0, 0.24, 1]

export function cubicBezier(x1, y1, x2, y2) {
  const cx = 3 * x1
  const bx = 3 * (x2 - x1) - cx
  const ax = 1 - cx - bx
  const cy = 3 * y1
  const by = 3 * (y2 - y1) - cy
  const ay = 1 - cy - by
  const sampleX = (s) => ((ax * s + bx) * s + cx) * s
  const sampleY = (s) => ((ay * s + by) * s + cy) * s
  const slopeX = (s) => (3 * ax * s + 2 * bx) * s + cx
  return (x) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    let s = x
    for (let i = 0; i < 8; i++) {
      const error = sampleX(s) - x
      if (Math.abs(error) < 1e-6) return sampleY(s)
      const slope = slopeX(s)
      if (Math.abs(slope) < 1e-6) break
      s -= error / slope
    }
    let lo = 0
    let hi = 1
    s = x
    while (hi - lo > 1e-6) {
      if (sampleX(s) < x) lo = s
      else hi = s
      s = (lo + hi) / 2
    }
