export function splitWordLoaderTimeline(options, timing = splitWordLoaderTiming) {
  const k = Math.max(options.durationScale, 0.05)
  if (options.reduced) {
    return {
      riseEnd: 0,
      openStart: 0,
      openEnd: 0,
      appear: [],
      expandStart: 0,
      expandEnd: 0,
      end: timing.fade * k,
