    void document.fonts?.ready.then(onFonts)

    return () => {
      stop()
      resize.disconnect()
      intersection.disconnect()
      document.fonts?.removeEventListener('loadingdone', onFonts)
    }
  }, [playKey, reduced, letterCount, imageCount, durationScale, imageRatio])

  const state = stage === 0 ? 'loading' : stage === 1 ? 'revealing' : 'done'

  return (
    <div
      className={['uig-split-word-loader', className].filter(Boolean).join(' ')}
      style={style}
      data-state={state}
    >
      <div className="uig-split-word-loader__content" inert={stage === 0}>
        {children}
      </div>
      {stage < 2 && (
        <div
          key={playKey}
          ref={overlayRef}
          role="status"
          className="uig-split-word-loader__overlay"
          style={{
            position: fixed ? 'fixed' : 'absolute',
            background,
            color,
            pointerEvents: stage === 1 ? 'none' : undefined,
          }}
        >
          <span className="uig-split-word-loader__status">{`${label} ${run.percent}%`}</span>
          <div
            ref={rowRef}
            aria-hidden="true"
            className="uig-split-word-loader__row"
            style={{
              fontFamily,
              fontWeight,
              fontSize: `${fontSize}cqw`,
              letterSpacing: `${letterSpacing}em`,
              lineHeight: 1,
            }}
          >
            <div ref={leftRef} className="uig-split-word-loader__left">
              {left.map((letter, i) => (
                <span key={i} className="uig-split-word-loader__letter">
                  {letter}
                </span>
              ))}
            </div>
            <span ref={slotRef} className="uig-split-word-loader__slot" />
            <div ref={rightRef} className="uig-split-word-loader__right">
              {right.map((letter, i) => (
                <span key={i} className="uig-split-word-loader__letter">
                  {letter}
                </span>
              ))}
            </div>
          </div>
          <div ref={boxRef} aria-hidden="true" className="uig-split-word-loader__box">
            {images.map((src, i) => (
              <img
                key={`${src}-${i}`}
                src={src}
                alt=""
                decoding="async"
                draggable={false}
                className="uig-split-word-loader__image"
              />
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

